// Botany and gardening — concept glossary (Hebrew): a page per key term, and per common tree, wildflower, desert
// plant, herb, house plant and poisonous plant of Israel. Plants that already have a page in /learn/fruits-vegetables
// (olive, date, fig, almond, etrog, prickly pear…) or a term page in /learn/science (photosynthesis, chlorophyll,
// root, pollination, germination) are linked from the lessons, not repeated. Facts checked against two sources
// (2026-10-31); protected status per the 2005 list as summarised by Hamichlol and the NPA, written cautiously where
// a species' status could not be confirmed. Every plant page says what not to touch or taste.
const q = (question, right, wrong, exp) => ({ q: question, options: [right, ...wrong], exp })
// kind 'term' → "<term> — מה זה?"; 'plant' → "<term> — איך מזהים…". Patterns unique to this subject.
const C = ({ kind = 'plant', ...c }) => {
  const fallback = kind === 'term'
    ? `${c.term}: מה זה בבוטניקה ובגינון, הסבר פשוט לילדים עם דוגמאות מהחיים, טיפ לזכירה וחידון קצר.`
    : `${c.term}: איך מזהים את הצמח, איפה הוא גדל בישראל, מתי הוא פורח ומה חשוב לדעת עליו. עם חידון.`
  return {
    title: kind === 'term' ? `${c.term} — מה זה?` : `${c.term} — הכירו את הצמח`,
    seoTitle: kind === 'term' ? `${c.term} — מה זה? מושג בבוטניקה ובגינון לילדים`
      : `${c.term} — איך מזהים, איפה גדל ועובדות לילדים`,
    seoDesc: [`${c.short} עם חידון.`, c.short, fallback].find(s => s.length >= 70 && s.length <= 168) || fallback,
    ...c
  }
}

